// domainspec-calculation-semantics: "domainspec.typed-calculation/v1"
use std::collections::BTreeMap;
fn domainspec_divide(left: u64, right: u64, rounding: &str) -> Result<u64, String> { if right == 0 { return Err("Calculation division by zero".to_owned()); } if rounding == "reject" && left % right != 0 { return Err("Calculation inexact division".to_owned()); } Ok(if rounding == "ceil" { left.div_ceil(right) } else { left / right }) }
pub fn line_subtotal(inputs: &BTreeMap<String, u64>) -> Result<u64, String> { (inputs.get("amount_minor").copied().ok_or_else(|| "missing UInt64 input:amount_minor".to_owned())?).checked_mul(inputs.get("requested_quantity").copied().ok_or_else(|| "missing UInt64 input:requested_quantity".to_owned())?).ok_or_else(|| "Calculation multiply range error".to_owned()) }
